// Scripted emergency flows. Written from general first-aid principles for the demo; they are NOT generated by AI
// and must be replaced by the mission's own medical checklist and flight-surgeon procedures.

export type Step =
  | { id: string; kind: 'ask'; text: string; detail?: string; yes: string; no: string }
  | { id: string; kind: 'do'; text: string; detail?: string; next: string }
  | { id: string; kind: 'record'; text: string; next: string }
  | { id: string; kind: 'end'; text: string; detail?: string }

export interface Protocol { id: string; title: string; subtitle: string; start: string; steps: Record<string, Step> }

const END: Step = {
  id: 'end', kind: 'end', text: 'Send the report to the flight surgeon now.',
  detail: 'AEGIS has drafted it from the steps and readings you recorded. Keep checking on your crewmate every few minutes.',
}

export const PROTOCOLS: Protocol[] = [
  {
    id: 'chest', title: 'Chest pain', subtitle: 'Pain or pressure in the chest', start: 'c1',
    steps: {
      c1: { id: 'c1', kind: 'do', text: 'Stop all activity and help your crewmate rest.', detail: 'Secure them in a comfortable position so they are not floating, and loosen tight clothing.', next: 'c2' },
      c2: { id: 'c2', kind: 'ask', text: 'Is your crewmate awake and able to answer you?', yes: 'c3', no: 'k1' },
      c3: { id: 'c3', kind: 'do', text: 'Alert the commander and the rest of the crew now.', next: 'c4' },
      c4: { id: 'c4', kind: 'do', text: 'Ask about the pain.', detail: 'Where is it? Does it spread to the arm, jaw or back? When did it start? Any shortness of breath, sweating or nausea? Write the answers in the note below.', next: 'c5' },
      c5: { id: 'c5', kind: 'record', text: 'Record heart rate and blood pressure with the medical kit monitor.', next: 'c6' },
      c6: { id: 'c6', kind: 'do', text: 'Follow the chest-pain procedure in your medical checklist.', detail: 'Do not give any medication unless the procedure or the flight surgeon tells you to. If your crewmate stops responding, choose “They collapsed”.', next: 'end' },
      k1: { id: 'k1', kind: 'do', text: 'Your crewmate is not responding: switch to the collapse steps.', next: 'k2' },
      ...collapseSteps('k'),
      end: END,
    },
  },
  {
    id: 'collapse', title: 'Collapsed or unresponsive', subtitle: 'A crewmate does not respond', start: 'k2',
    steps: { ...collapseSteps('k'), end: END },
  },
  {
    id: 'breath', title: 'Trouble breathing', subtitle: 'Short of breath or choking', start: 'b1',
    steps: {
      b1: { id: 'b1', kind: 'ask', text: 'Is a cabin air alarm sounding, or could there be smoke or fumes?', yes: 'b2', no: 'b3' },
      b2: { id: 'b2', kind: 'do', text: 'Follow the cabin air emergency procedure.', detail: 'Put on masks as trained and alert the whole crew before helping further.', next: 'b3' },
      b3: { id: 'b3', kind: 'ask', text: 'Can your crewmate speak in full sentences?', yes: 'b4', no: 'b5' },
      b4: { id: 'b4', kind: 'record', text: 'Record heart rate, blood pressure and temperature.', next: 'b6' },
      b5: { id: 'b5', kind: 'do', text: 'This is serious. Alert the commander and crew now.', detail: 'Bring the medical kit and oxygen, keep your crewmate upright and secured, and follow the onboard procedure.', next: 'b4' },
      b6: { id: 'b6', kind: 'do', text: 'Follow the breathing-difficulty procedure in your medical checklist.', next: 'end' },
      end: END,
    },
  },
]

function collapseSteps(p: string): Record<string, Step> {
  return {
    [`${p}2`]: { id: `${p}2`, kind: 'ask', text: 'Call their name loudly and tap their shoulders. Do they respond?', yes: `${p}3`, no: `${p}4` },
    [`${p}3`]: { id: `${p}3`, kind: 'do', text: 'Keep them still and secured, and alert the crew.', detail: 'Stay with them and watch their breathing.', next: `${p}8` },
    [`${p}4`]: { id: `${p}4`, kind: 'do', text: 'Call the whole crew for help now.', detail: 'Ask one person to bring the medical kit and the defibrillator (AED).', next: `${p}5` },
    [`${p}5`]: { id: `${p}5`, kind: 'ask', text: 'Look, listen and feel for up to 10 seconds. Are they breathing normally?', yes: `${p}6`, no: `${p}7` },
    [`${p}6`]: { id: `${p}6`, kind: 'do', text: 'Keep checking their breathing.', detail: 'Secure them so they stay in place. If breathing stops, start CPR.', next: `${p}8` },
    [`${p}7`]: { id: `${p}7`, kind: 'do', text: 'Start CPR as you were trained for weightlessness.', detail: 'Restrain your crewmate and yourself, use your mission’s CPR technique, and attach the AED as soon as it arrives. Follow its voice prompts.', next: `${p}8` },
    [`${p}8`]: { id: `${p}8`, kind: 'record', text: 'When possible, record heart rate and blood pressure.', next: 'end' },
  }
}
